#!/usr/bin/env python3
"""Stateless H1 input packet/assembly. No subprocess, hook or publication owner.

--packet prints a proposed SSH argv/stdin document; it NEVER executes it.
--assemble accepts nonsecret acquisition DATA, never approval or credentials.
--acquire is solely the bounded future remote body, held pending Root ruling.
"""
import base64
from contextlib import ExitStack
import hashlib
import json
import os
from pathlib import PurePosixPath
import pwd
import stat
import sys
import types

ROOT = '01a15741-5e68-7803-8eb4-ccac74a6c04b'
SOURCE_COMMIT = 'e7e1aa7205476f3b0b56b27e027a6768cc27d373'
USER, UID, GID, HOME = 'ubuntu0', 1000, 1000, '/home/ubuntu0'
LANE = HOME + '/lanes'
HELPER = LANE + '/ext/.host_glm_token.sh'
BOOT = '/usr/bin/python3.12'
IMAGE_SHA = 'e50d468e8b0adfb05733f5b87b3cff34829c4a8c1aea50c865aa8bdfe4bb150f'
OUTER_SHA = 'c7fc8be292b3f231317c3cc9e5b64c990a34a495cf0fa095048a37df0379b2f6'
CONTRACT = 'paid-host-env-held-fd-token-data.v1'
SCHEMA = 'mastermind.h1_initializer_input_acquisition/v1'
IDENTITY = ('st_dev','st_ino','st_mode','st_uid','st_gid','st_nlink','st_size','st_mtime_ns','st_ctime_ns')
MAX_DATA = 16384
# Exact reviewed private package, embedded by the source-only builder below.
SOURCES = {'paid_initializer.py': '', 'paid_initializer_token_data.py': '', 'paid_initializer_nested_data.py': ''}
PINS = {'paid_initializer.py': '14df9c41fd14125fa2407d4dc5ed2ff42ca3a6a69ffa34b005de45f458150559', 'paid_initializer_token_data.py': '7a3e5d2642df12c48769490c6cb86301bad1843088bf2dae48181c7a307e2dfe', 'paid_initializer_nested_data.py': '47c476deedd42231206d528b656664c8b590414ea905ee2fe91571a90454d073'}


class Refused(Exception):
    def __init__(self):
        super().__init__('h1_input_acquisition_refused')


def refuse():
    raise Refused() from None


def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()


def closed(value, keys):
    if type(value) is not dict or set(value) != set(keys): refuse()
    return value


def decode(raw):
    def pairs(items):
        value={}
        for key,item in items:
            if key in value: refuse()
            value[key]=item
        return value
    if type(raw) is not bytes or not 0<len(raw)<=MAX_DATA: refuse()
    try:
        return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda _:refuse())
    except (ValueError,UnicodeError,RecursionError): refuse()


def identity(info):
    return [getattr(info,key) for key in IDENTITY]


def package():
    name='_h1_qualified_input_package'
    parent=types.ModuleType(name);parent.__path__=[]
    loaded={};previous={key:sys.modules.get(key) for key in [name]+[name+'.'+n[:-3] for n in SOURCES]}
    try:
        sys.modules[name]=parent
        for filename in ('paid_initializer.py','paid_initializer_token_data.py','paid_initializer_nested_data.py'):
            raw=base64.b64decode(SOURCES[filename],validate=True)
            if hashlib.sha256(raw).hexdigest()!=PINS[filename]: refuse()
            full=name+'.'+filename[:-3];module=types.ModuleType(full)
            module.__package__=name;module.__file__='<qualified:'+filename+'>'
            sys.modules[full]=module
            exec(compile(raw,module.__file__,'exec'),module.__dict__)
            loaded[filename]=module
        return loaded
    finally:
        for key,value in previous.items():
            if value is None:sys.modules.pop(key,None)
            else:sys.modules[key]=value


class Custody:
    """Same finite nofollow/full9/native-ACL owner rules; never executes inputs."""
    def __init__(self): self.held=[]
    def __enter__(self):return self
    def __exit__(self,*args):
        failed=False
        for fd,_,_,_ in reversed(self.held):
            try:os.close(fd)
            except OSError:failed=True
        self.held.clear()
        if failed:refuse()
    @staticmethod
    def acl(fd):
        if any(n in ('system.posix_acl_access','system.posix_acl_default') for n in os.listxattr(fd)):refuse()
    def check(self):
        for fd,parent,name,before in self.held:
            self.acl(fd)
            actual=os.stat('/',follow_symlinks=False) if parent is None else os.stat(name,dir_fd=parent,follow_symlinks=False)
            if identity(os.fstat(fd))!=before or identity(actual)!=before:refuse()
    def open(self,path,*,owners,directory=False):
        if type(path) is not str or not path.startswith('/') or str(PurePosixPath(path))!=path or any(p in ('','.','..') for p in path.split('/')[1:]):refuse()
        parent=os.open('/',os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC)
        self.held.append((parent,None,None,None))
        anchor=os.fstat(parent)
        self.held[-1]=(parent,None,None,identity(anchor))
        self.acl(parent)
        if anchor.st_uid!=0 or not stat.S_ISDIR(anchor.st_mode) or anchor.st_mode&0o022:refuse()
        parts=path.split('/')[1:]
        for i,part in enumerate(parts):
            is_dir=i<len(parts)-1 or directory
            before=os.stat(part,dir_fd=parent,follow_symlinks=False)
            fd=os.open(part,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC|os.O_NONBLOCK|(os.O_DIRECTORY if is_dir else 0),dir_fd=parent)
            self.held.append((fd,parent,part,None));opened=os.fstat(fd)
            self.held[-1]=(fd,parent,part,identity(opened))
            self.acl(fd)
            if identity(before)!=identity(opened) or opened.st_uid not in owners or opened.st_mode&0o022 or (is_dir and not stat.S_ISDIR(opened.st_mode)) or (not is_dir and (not stat.S_ISREG(opened.st_mode) or opened.st_nlink!=1)):refuse()
            parent=fd
        self.check();return parent


def first_python(environment):
    if environment.get('HOME')!=HOME:refuse()
    if any(k in environment for k in ('BASH_ENV','ENV','PYTHONHOME','PYTHONEXECUTABLE','__PYVENV_LAUNCHER__')) or any(k.startswith(('BASH_FUNC_','LD_')) for k in environment):refuse()
    inherited=environment.get('PATH','')
    if type(inherited) is not str or len(inherited)>16384 or '\0' in inherited:refuse()
    # Same order as _capture_environment, exact c7 outer, then owner prepend.
    capture=LANE+'/venv/bin:'+HOME+'/.local/bin:/opt/homebrew/bin:'+inherited
    outer=HOME+'/.npm-global/bin:'+HOME+'/.local/bin:/opt/homebrew/bin:'+LANE+'/venv/bin:'+capture
    final=LANE+'/venv/bin:'+outer
    for directory in final.split(':'):
        path=os.path.join(directory,'python3')
        if os.path.isfile(path) and os.access(path,os.X_OK):
            if not path.startswith('/') or str(PurePosixPath(path))!=path:refuse()
            return path,final
    refuse()


def image(custody,logical):
    current=logical;links=[]
    for _ in range(9):
        before=os.lstat(current)
        if not stat.S_ISLNK(before.st_mode):break
        if before.st_uid!=0:refuse()
        custody.open(os.path.dirname(current),owners={0},directory=True)
        target=os.readlink(current);links.append((current,identity(before),target))
        current=os.path.normpath(target if target.startswith('/') else os.path.join(os.path.dirname(current),target))
    else:refuse()
    if current!=BOOT:refuse()
    fd=custody.open(current,owners={0});info=os.fstat(fd)
    if not info.st_mode&0o111 or not 0<info.st_size<=128*1024*1024:refuse()
    h=hashlib.sha256();offset=0
    while offset<info.st_size:
        raw=os.pread(fd,min(65536,info.st_size-offset),offset)
        if not raw:refuse()
        h.update(raw);offset+=len(raw)
    if h.hexdigest()!=IMAGE_SHA:refuse()
    custody.check()
    for path,before,target in links:
        if identity(os.lstat(path))!=before or os.readlink(path)!=target:refuse()
    return {'path':logical,'real_path':BOOT,'sha256':IMAGE_SHA},links


def read_helper(custody,contexts,token):
    fd=custody.open(HELPER,owners={0,UID});info=os.fstat(fd)
    if (info.st_uid,info.st_gid,stat.S_IMODE(info.st_mode),info.st_nlink,info.st_size)!=(UID,GID,0o600,1,token._SIZE):refuse()
    raw=os.pread(fd,token._SIZE+1,0);token.parse_helper_data(raw)
    expected={'sha256':hashlib.sha256(raw).hexdigest(),'size':len(raw),'uid':UID,'gid':GID,'mode':0o600}
    helper=contexts.enter_context(token.freeze_helper_data(fd,expected=expected));del raw
    return helper,info


def acquire():
    # Fixed public entry: no path/account/selector override or platform bypass.
    if sys.platform!='linux' or sys.version_info[:2]!=(3,12) or not (sys.flags.isolated and sys.flags.no_site and sys.dont_write_bytecode) or os.getuid()!=UID or os.geteuid()!=UID or os.getgid()!=GID or os.getegid()!=GID:refuse()
    account=pwd.getpwuid(UID)
    if (account.pw_name,account.pw_dir)!=(USER,HOME) or os.path.realpath('/proc/self/exe')!=BOOT:refuse()
    selected,final_path=first_python(os.environ)
    modules=package();token=modules['paid_initializer_token_data.py'];nested=modules['paid_initializer_nested_data.py']
    with Custody() as custody, ExitStack() as contexts:
        _,boot_links=image(custody,BOOT);launch,launch_links=image(custody,selected)
        config=os.environ.get('GLM_CONFIG') or HOME+'/.glm/config.json'
        context=nested.bind_effective_context({'HOME':HOME,'GLM_CONFIG':config,'PATH':final_path},expected_home=HOME,expected_glm_config=config,expected_python=selected,lane_root=LANE,contract=CONTRACT)
        helper,info=read_helper(custody,contexts,token)
        custody.check();helper.check()
        for path,before,target in boot_links+launch_links:
            if identity(os.lstat(path))!=before or os.readlink(path)!=target:refuse()
        result={'schema_version':SCHEMA,'host_ref':'ubuntu0','transport_alias':'mmx-ubuntu0',
            'account':{'uid':UID,'gid':GID,'user':USER,'home':HOME},
            'helper':{'path':HELPER,'fingerprint':helper.fingerprint,'origin_identity':identity(info)},
            'selectors':{'home':context['home'],'glm_config':context['glm_config'],'launch_python':launch,'startup_basis':'RETAINED_EXPECTATION_NOT_GETPATH_PROOF'},
            'custody':'HELD_NAMED_FULL9_ACL_CHECKED_NOT_APPROVAL'}
        # Snapshot disposal precedes final namespace check and DATA return.
        contexts.close();custody.check()
    return result


def assemble(data):
    closed(data,('schema_version','host_ref','transport_alias','account','helper','selectors','custody'))
    if (data['schema_version'],data['host_ref'],data['transport_alias'],data['custody'])!=(SCHEMA,'ubuntu0','mmx-ubuntu0','HELD_NAMED_FULL9_ACL_CHECKED_NOT_APPROVAL'):refuse()
    if data['account']!={'uid':UID,'gid':GID,'user':USER,'home':HOME}:refuse()
    helper=closed(data['helper'],('path','fingerprint','origin_identity'));fp=closed(helper['fingerprint'],('schema_version','sha256','size','uid','gid','mode'))
    selectors=closed(data['selectors'],('home','glm_config','launch_python','startup_basis'))
    modules=package();token=modules['paid_initializer_token_data.py'];parent=modules['paid_initializer.py']
    if helper['path']!=HELPER or fp['schema_version']!=token.SCHEMA:refuse()
    wanted=token._expected({k:fp[k] for k in ('sha256','size','uid','gid','mode')})
    observed=helper['origin_identity']
    if type(observed) is not list or len(observed)!=9 or any(type(i) is not int or i<0 for i in observed):refuse()
    if (observed[3],observed[4],stat.S_IMODE(observed[2]),observed[5],observed[6])!=(UID,GID,0o600,1,wanted['size']) or not stat.S_ISREG(observed[2]):refuse()
    launch=closed(selectors['launch_python'],('path','real_path','sha256'))
    if selectors['home']!=HOME or selectors['startup_basis']!='RETAINED_EXPECTATION_NOT_GETPATH_PROOF' or launch['real_path']!=BOOT or launch['sha256']!=IMAGE_SHA:refuse()
    value={'schema_version':parent.SCHEMA,'host_ref':'ubuntu0','transport_alias':'mmx-ubuntu0','lane_root':LANE,'account':data['account'],
       'bootstrap_python':{'path':BOOT,'real_path':BOOT,'sha256':IMAGE_SHA},'launch_python':launch,
       'host_env':{'path':LANE+'/ext/HOST_ENV.sh','sha256':OUTER_SHA,'size':587,'uid':UID,'gid':GID,'mode':0o755},
       'nested_helper':{'path':HELPER,**wanted},'initialized_context':{'home':HOME,'glm_config':selectors['glm_config']},
       'initialization_contract':CONTRACT,'purpose':parent.PURPOSE,'startup':{'profile':'cpython-3.12-linux-root-prefix.v1',**dict.fromkeys(('prefix','exec_prefix','base_prefix','base_exec_prefix'),'/usr')}}
    value=parent.validate_commitment(value,host_ref='ubuntu0',transport_alias='mmx-ubuntu0',python_path=launch['path'],capture_root=LANE+'/ext/lanes')
    raw=parent.canonical(value)
    return {'schema_version':'mastermind.h1_initializer_commitment_candidate/v1','status':'DATA_CANDIDATE_NOT_APPROVAL_NOT_QUALIFICATION','commitment':value,'commitment_sha256':hashlib.sha256(raw).hexdigest(),'canonical_utf8':raw.decode()}


def packet(source):
    # Packet itself contains public source and selectors only, never credentials.
    payload=base64.b64encode(source).decode()
    body="import base64\n_s={'__name__':'_h1_acquisition_packet'}\nexec(compile(base64.b64decode("+repr(payload)+",validate=True),'<pinned-h1-acquisition>','exec'),_s)\nraise SystemExit(_s['main'](['--acquire']))\n"
    return {'schema_version':'mastermind.h1_acquisition_packet/v1','status':'PROPOSED_NOT_EXECUTED','root':ROOT,'local_uid':501,'timeout_seconds':35,'output_cap_bytes':65536,
       'argv':['/usr/bin/ssh','-T','-oBatchMode=yes','-oStrictHostKeyChecking=yes','-oUpdateHostKeys=no','-oConnectTimeout=8','mmx-ubuntu0',BOOT+' -I -S -B -'],
       'stdin_utf8':body,'stdin_sha256':hashlib.sha256(body.encode()).hexdigest(),'source_sha256':hashlib.sha256(source).hexdigest(),'qualified_dependencies':PINS}


def main(argv=None):
    try:
        args=sys.argv[1:] if argv is None else argv
        if args==['--packet']:
            output=packet(open(__file__,'rb').read())
        elif args==['--assemble']:
            output=assemble(decode(sys.stdin.buffer.read(MAX_DATA+1)))
        elif args==['--acquire']:
            output=acquire()
        else:refuse()
        raw=canonical(output)+b'\n'
        if args!=['--packet'] and len(raw)>65536:refuse()
        sys.stdout.buffer.write(raw);return 0
    except BaseException:
        # Secret-bearing exception repr/context never crosses this boundary.
        try:sys.stderr.write('h1_input_acquisition_refused\n')
        except BaseException:pass
        return 78


if __name__=='__main__':
    raise SystemExit(main())
